package glitch

import data.glitch_lib

# High-confidence suspicious markers (actionable, urgent)
action_markers := {"todo", "fixme", "xxx", "hack", "temporary", "workaround", "work-around", "kludge", "bodge", "stopgap"}

# Security-specific deferred work
security_deferred := {"insecure", "hardcoded", "skip verify", "skip_verify", "disabled check", "disabled_check", "without verification", "no verification"}

# Combine for security context check
all_suspicious := {pattern | pattern := action_markers[_]} | {pattern | pattern := security_deferred[_]}

# Security-sensitive keywords that create high-risk context
security_keywords := {"password", "secret", "key", "token", "cert", "credential", "auth", "login", "permission", "acl", "firewall", "encryption", "tls", "ssl", "kms", "root", "admin", "owner", "role", "privilege", "private", "public key", "secret key", "access key"}

# Common boilerplate patterns to exclude (license headers, standard disclaimers)
boilerplate_patterns := {"license", "copyright", "all rights reserved", "distributed under", "warrant", "merchantability", "fitness for purpose", "as is", "without warranty", "trademark"}

# Check if content has actionable marker with word boundaries
has_actionable_marker(content) {
    marker := action_markers[_]
    regex.match(sprintf("(?i)\\b%s\\b", [marker]), content)
}

# Check for security-deferred patterns
has_security_deferred(content) {
    pattern := security_deferred[_]
    regex.match(sprintf("(?i)%s", [pattern]), content)
}

# Check for security context
has_security_context(content) {
    kw := security_keywords[_]
    regex.match(sprintf("(?i)\\b%s\\b", [kw]), content)
}

# Check if likely boilerplate (exclude these)
is_boilerplate(content) {
    bp := boilerplate_patterns[_]
    regex.match(sprintf("(?i)\\b%s\\b", [bp]), content)
}

# Require stronger signal: actionable marker + (security context OR security-deferred pattern)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    comment := parent.comments[_]

    # Must have high-confidence actionable marker
    has_actionable_marker(comment.content)

    # Must also have security context or security-deferred pattern
    has_security_context(comment.content)

    # Exclude obvious boilerplate
    not is_boilerplate(comment.content)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious security-related comment - Comments with security-sensitive context and actionable incomplete/deferral markers indicate potential security debt. (CWE-546)"
    }
}

# Security-deferred patterns alone are high confidence
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    comment := parent.comments[_]

    has_security_deferred(comment.content)

    # Exclude obvious boilerplate
    not is_boilerplate(comment.content)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious comment detected - Comments containing security-deferred patterns indicate potentially insecure temporary configurations. (CWE-546)"
    }
}

