import data.glitch_lib

# URL patterns indicating external issue/bug trackers
issue_url_patterns := {"issues/", "issue/", "bugs/", "bug/", "tickets/", "ticket/", "tracker.", "/issues#", "/issue#", "github.com/", "bitbucket.org/", "jira.", "bugzilla.", "redmine."}

# Comments embedded in code (IR parser failed to extract as Comment nodes)
extract_comment_pattern := "#[^\\n]*|//[^\\n]*|/\\*[^*]*\\*+(?:[^/*][^*]*\\*+)*/"

# Detect issue tracker URL references in comments
has_issue_url(content) {
    pattern := issue_url_patterns[_]
    regex.match(sprintf("(?i)%s", [pattern]), content)
}

# Detect any external reference indicator
has_external_reference(content) {
    regex.match("(?i)(https?://|http://|ftp://)", content)
}

# Extract embedded comments from code strings and check for TODO/FIXME markers
embedded_comment_has_marker(code_str) {
    regex.match("(?i)#\\s*(TODO|FIXME|XXX|HACK|temporary|NOTE)[^\\n]*", code_str)
}

# Walk through all nodes to find code strings containing embedded comments with markers
all_code_strings_with_comments(node) = results {
    results = {r |
        walk(node, [_, n])
        n.code
        is_string(n.code)
        embedded_comment_has_marker(n.code)
        r := {
            "content": n.code,
            "line": n.line
        }
    }
}

# Main: detect issue tracker URL references in formal comments
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    comment := parent.comments[_]

    # Detect comments that are primarily external issue references
    has_issue_url(comment.content)
    has_external_reference(comment.content)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious comment detected - Issue tracker URL reference indicates deferred work or known problem without resolution context. (CWE-546)"
    }
}

# Detect embedded TODO/FIXME comments in code nodes (IR parser missed these)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
