package glitch

import data.glitch_lib

# Actionable markers indicating incomplete/deferred work
actionable_markers := {"TODO", "FIXME", "XXX", "HACK", "TEMP", "TEMPORARY", "FUTURE", "PENDING", "POSTPONED", "DEFER", "DEFERRED"}

# Security-related keywords that combined with actionable markers indicate risk
security_keywords := {"INSECURE", "PASSWORD", "SECRET", "KEY", "TOKEN", "CERT", "AUTH", "LOGIN", "ENCRYPTION", "TLS", "SSL", "VERIFY", "VALIDATION", "HARDCODED", "SKIP", "DISABLE", "BYPASS", "WORKAROUND"}

# Patterns indicating fragile implementation or known breakage
fragile_patterns := {"break", "broken", "will not work", "does not work", "cannot change", "do not change", "hardcoded", "limitation", "known issue", "doesn't work", "won't work", "fragile", "brittle"}

# Detect standalone actionable marker (standalone word)
has_actionable_marker(content) {
    marker := actionable_markers[_]
    regex.match(sprintf("(?i)(^|[^a-zA-Z])%s($|[^a-zA-Z])", [marker]), content)
}

# Detect actionable marker combined with security context
has_security_debt(content) {
    has_actionable_marker(content)
    keyword := security_keywords[_]
    regex.match(sprintf("(?i)%s", [keyword]), content)
}

# Detect comment indicating fragile/known-broken implementation without fix
indicates_fragility(content) {
    pattern := fragile_patterns[_]
    regex.match(sprintf("(?i)%s", [pattern]), content)
    not regex.match("(?i)(fix|resolved|workaround implemented|solution)", content)
}

# Detect NOTE with actionable/security implication (not just documentation)
is_concerning_note(content) {
    regex.match("(?i)^\\s*NOTE\\s*[:\\-]", content)
    indicates_fragility(content)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    comment := parent.comments[_]

    # Skip pure documentation patterns
    not regex.match("(?i)^\\s*(copyright|license|author|maintainer|source|reference)[:\\s]", comment.content)

    # Detect actionable security debt, fragility, or concerning notes
    {
        has_security_debt(comment.content)
    } {
        is_concerning_note(comment.content)
    } {
        indicates_fragility(comment.content)
        regex.match("(?i)(currently|at this time|for now|presently)", comment.content)
    }

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious comment detected - Comment indicates incomplete implementation, deferred security work, or fragile configuration that may pose security risks. (CWE-546)"
    }
}

# Detect embedded actionable markers in code strings when IR parser misses them
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Find code strings with embedded actionable markers
    [_, node] := walk(parent)
    node.code
    is_string(node.code)
    content := node.code

    # Must have actionable marker
    has_actionable_marker(content)

    # Must have security implication or fragility indicator
    {
        keyword := security_keywords[_]
        regex.match(sprintf("(?i)%s", [keyword]), content)
    } {
        pattern := fragile_patterns[_]
        regex.match(sprintf("(?i)%s", [pattern]), content)
    }

    # Create synthetic element pointing to actual line where marker appears
    synthetic := {
        "ir_type": "Comment",
        "line": node.line,
        "code": content,
        "content": content
    }

    result := {
        "type": "sec_susp_comm",
        "element": synthetic,
        "path": parent.path,
        "description": "Suspicious comment detected - Embedded TODO/FIXME or marker indicates incomplete implementation with security implications. (CWE-546)"
    }
}

